package setup

import (
	"fmt"
	"io"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

// The commands of zmdhparam and the number of bits it generated by default.
const (
	dhCmdGet      = "get"
	dhCmdSet      = "set"
	dhDefaultBits = 2048
)

// dhOptions are the command and the options of zmdhparam.
type dhOptions struct {
	Command string
	In, Out string // -in, -out: a file, "-" for stdin/stdout
	HasIn   bool
	HasOut  bool
	// Bits is the size asked with -new; HasNew tells that -new was given
	// (with no number, Bits is 0).
	Bits   int
	HasNew bool
	// Debug is the -debug level: 0 off, a bare -debug is 1.
	Debug     int
	Help, Man bool
}

// dhOptKind says what an option takes: nothing, a string, an optional integer.
type dhOptKind int

const (
	dhFlag dhOptKind = iota
	dhString
	dhOptInt
)

// The names of the options.
const (
	dhOptIn    = "in"
	dhOptOut   = "out"
	dhOptLDAP  = "ldap"
	dhOptNew   = "new"
	dhOptHelp  = "help"
	dhOptMan   = "man"
	dhOptDebug = "debug"
)

var dhIntRE = regexp.MustCompile(`^-?\d+$`)

// dhOptionKinds are the options of Opts::_process_options (Getopt::Long
// "in=s", "out=s", "ldap", "new:i", "help", "man", "debug:1"), by name.
var dhOptionKinds = map[string]dhOptKind{
	dhOptIn: dhString, dhOptOut: dhString, dhOptLDAP: dhFlag, dhOptNew: dhOptInt,
	dhOptHelp: dhFlag, dhOptMan: dhFlag, dhOptDebug: dhOptInt,
}

// dhOptionNames are the options a command takes: none of the file and size
// options without a valid command (the script parsed only -help, -man and
// -debug then), and -new only for set.
func dhOptionNames(cmd string) []string {
	switch cmd {
	case dhCmdGet:
		return []string{dhOptIn, dhOptOut, dhOptLDAP, dhOptHelp, dhOptMan, dhOptDebug}
	case dhCmdSet:
		return []string{dhOptIn, dhOptOut, dhOptLDAP, dhOptNew, dhOptHelp, dhOptMan, dhOptDebug}
	}

	return []string{dhOptHelp, dhOptMan, dhOptDebug}
}

// dhParse is the result of reading the command line: the options, the
// problems the script reported before its usage text (errs), and whether the
// options parsed at all (when they did not, the details are on stderr and
// only the short usage is printed).
type dhParse struct {
	opts   dhOptions
	errs   []string
	parsed bool
}

// parseDHParamArgs reads args as the script did: the command first (get or
// set), then Getopt::Long options (a single or double dash, any case, a unique
// abbreviation, "-name=value" or "-name value"), mixed with arguments that
// the script then rejected as unexpected. Messages of the option parser go to
// stderr.
func parseDHParamArgs(args []string, stderr io.Writer) *dhParse {
	p := &dhParse{parsed: true}

	if len(args) == 0 || strings.HasPrefix(args[0], "-") {
		p.errs = append(p.errs, "a command must be specified")
	} else if args[0] == dhCmdGet || args[0] == dhCmdSet {
		p.opts.Command, args = args[0], args[1:]
	}

	names := dhOptionNames(p.opts.Command)

	var rest []string

	for i := 0; i < len(args); {
		a := args[i]
		i++

		switch {
		case a == "--":
			rest = append(rest, args[i:]...)
			i = len(args)
		case len(a) < 2 || a[0] != '-':
			rest = append(rest, a)
		default:
			var msg string

			if i, msg = p.opts.parseOption(a, args, i, names); msg != "" {
				_, _ = fmt.Fprintln(stderr, msg)

				p.parsed = false
			}
		}
	}

	p.check(rest)

	return p
}

// parseOption applies the option arg (with its dashes) and returns the index
// of the next argument, after any value it consumed, and what Getopt::Long
// would have complained about ("" when nothing).
func (o *dhOptions) parseOption(arg string, args []string, next int, names []string) (after int, msg string) {
	name, value, hasValue := strings.Cut(strings.TrimPrefix(strings.TrimPrefix(arg, "-"), "-"), "=")

	name, msg = dhMatchOption(name, names)
	if msg != "" {
		return next, msg
	}

	val := value

	switch kind := dhOptionKinds[name]; {
	case kind == dhFlag && hasValue:
		return next, "Option " + name + " does not take an argument"
	case kind == dhString && !hasValue:
		if next >= len(args) {
			return next, "Option " + name + " requires an argument"
		}

		val, next = args[next], next+1
	case kind == dhOptInt && !hasValue && next < len(args) && dhIntRE.MatchString(args[next]):
		val, next = args[next], next+1
	}

	return next, o.apply(name, val)
}

// dhMatchOption is the option that name stands for among names: exact, else
// the only one it abbreviates; otherwise the complaint.
func dhMatchOption(name string, names []string) (match, msg string) {
	name = strings.ToLower(name)

	var found []string

	for _, n := range names {
		if n == name {
			return n, ""
		}

		if name != "" && strings.HasPrefix(n, name) {
			found = append(found, n)
		}
	}

	switch len(found) {
	case 0:
		return "", "Unknown option: " + name
	case 1:
		return found[0], ""
	}

	return "", "Option " + name + " is ambiguous (" + strings.Join(found, ", ") + ")"
}

// apply records the value of an option, "" for an integer option that has none
// (0 for -new, 1 for -debug); it returns the complaint about a value that is
// not a number.
func (o *dhOptions) apply(name, val string) string {
	n := 0

	if (name == dhOptNew || name == dhOptDebug) && val != "" {
		var err error

		if n, err = strconv.Atoi(val); err != nil {
			return fmt.Sprintf("Value %q invalid for option %s (number expected)", val, name)
		}
	}

	switch name {
	case dhOptIn:
		o.In, o.HasIn = val, true
	case dhOptOut:
		o.Out, o.HasOut = val, true
	case dhOptNew:
		o.Bits, o.HasNew = n, true
	case dhOptDebug:
		o.Debug = max(n, 0)
		if val == "" {
			o.Debug = 1
		}
	case dhOptHelp:
		o.Help = true
	case dhOptMan:
		o.Man = true
	}

	return ""
}

// check adds the problems the script found in the options as a whole: more
// than the command and its options, -in and -out naming one file, and for
// set neither or both of -new and -in.
func (p *dhParse) check(rest []string) {
	o := &p.opts

	if len(rest) > 0 {
		p.errs = append(p.errs, "unexpected argument(s): "+strings.Join(rest, " "))
	}

	if o.HasIn && o.HasOut && o.In != "-" && o.Out != "-" && dhSameFile(o.In, o.Out) {
		p.errs = append(p.errs, "-in and -out can not match")
	}

	if o.Command != dhCmdSet {
		return
	}

	switch {
	case o.HasNew && o.HasIn:
		p.errs = append(p.errs, "-new and -in are exclusive arguments")
	case !o.HasNew && !o.HasIn:
		p.errs = append(p.errs, "-new or -in must be specified")
	}
}

// dhSameFile is whether two paths are the same file, as Cwd::abs_path told.
func dhSameFile(a, b string) bool {
	pa, errA := filepath.Abs(a)
	pb, errB := filepath.Abs(b)

	return errA == nil && errB == nil && pa == pb
}
